package com.godjiismp.weapons;
import com.godjiismp.skills.Skills;import net.fabricmc.fabric.api.entity.event.v1.ServerLivingEntityEvents;import net.minecraft.core.particles.ParticleTypes;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.entity.Entity;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.entity.monster.Monster;import net.minecraft.world.entity.monster.Skeleton;import net.minecraft.world.entity.monster.Zombie;import net.minecraft.world.phys.AABB;import net.minecraft.world.phys.Vec3;import java.util.*;
public final class WeaponAbilities {private WeaponAbilities(){}private record Combo(int hits,long tick){}private static final Map<UUID,Combo> COMBOS=new HashMap<>();private static final Set<UUID> TRIGGERING=new HashSet<>();public static void init(){ServerLivingEntityEvents.AFTER_DAMAGE.register((target,source,base,dealt,blocked)->{Entity attacker=source.getEntity();if(attacker instanceof net.minecraft.world.entity.projectile.Projectile p)attacker=p.getOwner();if(!(attacker instanceof ServerPlayer player)||dealt<=0||TRIGGERING.contains(player.getUUID())||player.getMainHandItem().getItem()!=LegendaryItems.get(1))return;long now=player.serverLevel().getGameTime();Combo c=COMBOS.get(player.getUUID());if(c==null||now-c.tick()>WeaponsConfig.comboWindowSeconds*20L)COMBOS.put(player.getUUID(),new Combo(1,now));else if(c.hits()+1>=WeaponsConfig.comboHits){COMBOS.remove(player.getUUID());int req=WeaponsConfig.requiredAttack[1];if(Skills.level(player,0)<req){player.sendSystemMessage(net.minecraft.network.chat.Component.literal("Requires Attack Lv"+req));return;}if(!player.getCooldowns().isOnCooldown(LegendaryItems.get(1))){chainStrike(player,target);player.getCooldowns().addCooldown(LegendaryItems.get(1),WeaponsConfig.cooldownSeconds[1]*20);}}else COMBOS.put(player.getUUID(),new Combo(c.hits()+1,now));});}
 public static void boneWave(ServerPlayer p){Vec3 start=p.getEyePosition(),dir=p.getLookAngle();double range=WeaponsConfig.radius[0];AABB area=p.getBoundingBox().expandTowards(dir.scale(range)).inflate(1);for(LivingEntity e:p.serverLevel().getEntitiesOfClass(LivingEntity.class,area,x->x!=p&&x.isAlive())){Vec3 rel=e.getBoundingBox().getCenter().subtract(start);double along=rel.dot(dir);if(along>=0&&along<=range&&rel.subtract(dir.scale(along)).length()<=WeaponsConfig.waveHalfWidth)hurt(p,e,WeaponsConfig.abilityDamage[0]*(isUndead(e)?WeaponsConfig.specialVsUndead[0]:1));}for(double d=0;d<=range;d+=.5){Vec3 at=start.add(dir.scale(d));p.serverLevel().sendParticles(ParticleTypes.SWEEP_ATTACK,at.x,at.y,at.z,1,.05,.05,.05,0);}}
 public static void groundSlam(ServerPlayer p){double r=WeaponsConfig.radius[2];AABB area=p.getBoundingBox().inflate(r,2,r);for(LivingEntity e:p.serverLevel().getEntitiesOfClass(LivingEntity.class,area,x->x!=p&&x.isAlive())){hurt(p,e,WeaponsConfig.abilityDamage[2]);Vec3 away=e.position().subtract(p.position()).normalize().scale(WeaponsConfig.hammerPushHorizontal);e.push(away.x,WeaponsConfig.hammerPushVertical,away.z);}p.serverLevel().sendParticles(ParticleTypes.POOF,p.getX(),p.getY(),p.getZ(),18,r/2,.1,r/2,.03);}
 private static void chainStrike(ServerPlayer p,LivingEntity first){List<LivingEntity> targets=new ArrayList<>();if(first.isAlive())targets.add(first);double radius=WeaponsConfig.radius[1];LivingEntity previous=first;for(int hop=0;hop<WeaponsConfig.chainTargets[1];hop++){LivingEntity origin=previous;LivingEntity next=p.serverLevel().getEntitiesOfClass(LivingEntity.class,origin.getBoundingBox().inflate(radius),x->x instanceof Monster&&x!=p&&x.isAlive()&&!targets.contains(x)).stream().min(Comparator.comparingDouble(origin::distanceToSqr)).orElse(null);if(next==null)break;targets.add(next);previous=next;}TRIGGERING.add(p.getUUID());try{for(LivingEntity e:targets){hurt(p,e,WeaponsConfig.abilityDamage[1]);p.serverLevel().sendParticles(ParticleTypes.ELECTRIC_SPARK,e.getX(),e.getY()+e.getBbHeight()/2,e.getZ(),12,.3,.4,.3,.04);p.serverLevel().levelEvent(3002,net.minecraft.core.BlockPos.containing(e.position()),0);}}finally{TRIGGERING.remove(p.getUUID());}}
 private static void hurt(ServerPlayer p,LivingEntity e,double damage){if(e instanceof net.minecraft.world.entity.player.Player&&!p.server.getPlayerList().isPvpAllowed())return;double amount=damage;if(e instanceof net.minecraft.world.entity.player.Player){int weapon=0;for(int i=0;i<6;i++)if(p.getMainHandItem().getItem()==LegendaryItems.get(i)){weapon=i;break;}amount*=WeaponsConfig.pvpMultiplier[weapon];}e.hurt(p.damageSources().playerAttack(p),(float)amount);}
 private static boolean isUndead(LivingEntity e){return e instanceof Zombie||e instanceof Skeleton;}}



